with r as (select c.*,g.latitude,g.longitude,row_number() over(partition by customer_unique_id order by ingested_at desc nulls last,customer_id) rn from {{ ref('stg_customers') }} c left join {{ ref('int_geolocation_by_zip') }} g on c.customer_zip_code_prefix=g.geolocation_zip_code_prefix) select customer_unique_id,customer_zip_code_prefix,customer_city,customer_state,latitude,longitude from r where rn=1
